text:
.chromeclass-toolbar {
  overflow-x: hidden;

  & toolbarseparator {
    appearance: none;
    min-inline-size: 1px;
    background-image: linear-gradient(
      transparent 4px,
      var(--toolbarseparator-color) 4px,
      var(--toolbarseparator-color) calc(100% - 4px),
      transparent calc(100% - 4px)
    );
    margin-inline: 1px;
    padding: 0;

    &::before {
      display: none;
    }
  }
}
